import React from 'react';
import './HomePage.css';

function HomePage() {
  return (
    <div className="homepage">
      <div className="hero-section">
        <h1>Welcome to Cadence Music</h1>
        <p className="tagline">Your personal music experience</p>
        <div className="featured-content">
          <img src="/covers/default-cover.jpg" alt="Featured" className="featured-cover" />
          <p>Discover and enjoy your favorite tracks</p>
        </div>
      </div>
    </div>
  );
}

export default HomePage;
